  render: () => {
    const ref1 = useRef(null);
    const ref2 = useRef(null);
    const [open, setOpen] = useState(false);
    const steps: TourProps['steps'] = [{
      title: 'Custom Styling',
      description: 'This tour has a custom mask with different color and opacity.',
      target: () => ref1.current
    }, {
      title: 'Second Step',
      description: 'Notice the bluish overlay instead of the default dark one.',
      target: () => ref2.current
    }];
    return <>\r
        <Space>\r
          <Button ref={ref1}>First Button</Button>\r
          <Button ref={ref2}>Second Button</Button>\r
        </Space>\r
        <Divider />\r
        <Button type="primary" onClick={() => setOpen(true)}>\r
          Start Custom Mask Tour\r
        </Button>\r
        <Tour open={open} onClose={() => setOpen(false)} steps={steps} mask={{
        style: {
          boxShadow: 'inset 0 0 15px #1890ff'
        },
        color: 'rgba(24, 144, 255, 0.4)'
      }} />\r
      </>;
  }
